mapper.select:
select *
from t_payment_order
where order_no = #{orderNo}
  and request_id = #{requestId}
limit 1
for update

select *
from t_payment_order
where order_no = #{orderNo}
  and payment_app_id = #{paymentAppId}
  and protocol = #{protocol}
  and status = 'PENDING'
  and (expires_at is null or expires_at > current_timestamp)
order by id desc
limit 1
for update

select *
from t_payment_order
where payment_app_id = #{paymentAppId}
  and channel_merchant_order_no = #{channelMerchantOrderNo}
limit 1

select *
from t_payment_order
where payment_app_id = #{paymentAppId}
  and channel_transaction_id = #{channelTransactionId}
limit 1

mapper.update:
update t_payment_order
set status = #{targetStatus},
    update_time = current_timestamp
where payment_no = #{paymentNo}
  and status = #{currentStatus}

update t_payment_order
set status = #{targetStatus},
    payment_params = case
        when #{paymentParams} is null then payment_params
        else #{paymentParams}
    end,
    update_time = current_timestamp
where payment_no = #{paymentNo}
  and status = #{currentStatus}
